    return response.json()

@patch('payments.gateway.charge_customer')
def test_charge_customer(mock_charge_customer):
    mock_charge_customer.return_value = {'status': 'ok'}
    assert charge_customer('cust_1', 100) == {'status': 'ok'}

def get_account(request):
    account_id = request.headers.get('X-Account-Id')
    is_admin = request.headers.get('X-Is-Admin') == 'true'
    if is_admin:
        return db.accounts.get_full(account_id)
    return db.accounts.get_public(account_id)

